import { Color, ColorblindnessType } from '../../lib/color.js';
import { Fraction } from '../../lib/helper.js';
import { asU8, clampF64 } from '../../lib/rustfmt.js';
import { getMixingFunction } from '../colorspace.js';
import { Panic } from '../error.js';
import { ColorArgIterator, numberArg, PrintSpectrum } from './io.js';

/**
 * Base of the commands generated by the `color_command!` macro: `transform` computes the new
 * color, which is then shown.
 */
class TransformingColorCommand {
  /**
   * @param {import('../output.js').Output} out
   * @param {object} matches
   * @param {import('../config.js').Config} config
   * @param {Color} color
   */
  run(out, matches, config, color) {
    const output = this.transform(matches, config, color);
    out.showColor(config, output);
  }
}

/** `pastel saturate`. */
export class SaturateCommand extends TransformingColorCommand {
  /**
   * Increases the saturation by the `amount` argument.
   * @param {object} matches
   * @param {import('../config.js').Config} _config
   * @param {Color} color
   * @returns {Color}
   */
  transform(matches, _config, color) {
    const amount = numberArg(matches, 'amount');
    return color.saturate(amount);
  }
}

