/** `pastel mix`: mixes the base color into every input color. */
export class MixCommand extends TransformingColorCommand {
  /**
   * Mixes the `base` argument into the color in the color space of the `colorspace` argument; the
   * `fraction` argument is the share of the base color.
   * @param {object} matches
   * @param {import('../config.js').Config} config
   * @param {Color} color
   * @returns {Color}
   */
  transform(matches, config, color) {
    const printSpectrum = { value: PrintSpectrum.Yes };

    const base = ColorArgIterator.fromColorArg(config, matches.getOne('base'), printSpectrum);
    const fraction = Fraction.from(1.0 - numberArg(matches, 'fraction'));

    const mix = getMixingFunction(matches.getOne('colorspace'));

    return mix(base, color, fraction);
  }
}

/** `pastel colorblind`: simulates a colorblindness type. */
export class ColorblindCommand extends TransformingColorCommand {
  /**
   * Simulates the colorblindness selected by the `type` argument.
   * @param {object} matches
   * @param {import('../config.js').Config} _config
   * @param {Color} color
   * @returns {Color}
   */
  transform(matches, _config, color) {
    // The type of colorblindness selected (protanopia, deuteranopia, tritanopia)
    const cbTy = matches.getOne('type').toLowerCase();

    let type;
    switch (cbTy) {
      case 'prot':
        type = ColorblindnessType.Protanopia;
        break;
      case 'deuter':
        type = ColorblindnessType.Deuteranopia;
        break;
      case 'trit':
        type = ColorblindnessType.Tritanopia;
        break;
      default:
        throw new Panic(
          'internal error: entered unreachable code: Unknown property',
          'src/cli/commands/color_commands.rs:99:13',
        );
    }

    return color.simulateColorblindness(type);
  }
}

/** `pastel set`: sets a color property to a specific value. */
export class SetCommand extends TransformingColorCommand {
  /**
   * Sets the channel named by the `property` argument to the `value` argument.
   * @param {object} matches
   * @param {import('../config.js').Config} _config
   * @param {Color} color
   * @returns {Color}
   */
  transform(matches, _config, color) {
    const property = matches.getOne('property').toLowerCase();

    const value = numberArg(matches, 'value');

    switch (property) {
      case 'red':
      case 'green':
      case 'blue': {
        const rgba = color.toRgba();
        const channel = asU8(clampF64(0.0, 255.0, value));
        if (property === 'red') {
          rgba.r = channel;
        } else if (property === 'green') {
          rgba.g = channel;
        } else {
          rgba.b = channel;
        }
        return Color.fromRgba(rgba.r, rgba.g, rgba.b, rgba.alpha);
      }
      case 'hsl-hue':
      case 'hsl-saturation':
      case 'hsl-lightness': {
        const hsla = color.toHsla();
        if (property === 'hsl-hue') {
          hsla.h = value;
        } else if (property === 'hsl-saturation') {
          hsla.s = value;
        } else {
          hsla.l = value;
        }
        return Color.fromHsla(hsla.h, hsla.s, hsla.l, hsla.alpha);
      }
      case 'oklab-l':
      case 'oklab-a':
      case 'oklab-b': {
        const oklab = color.toOklab();
        if (property === 'oklab-l') {
          oklab.l = value;
        } else if (property === 'oklab-a') {
          oklab.a = value;
        } else {
          oklab.b = value;
        }
        return Color.fromOklab(oklab.l, oklab.a, oklab.b, oklab.alpha);
      }
      case 'lightness':
      case 'lab-a':
      case 'lab-b': {
        const lab = color.toLab();
        if (property === 'lightness') {
          lab.l = value;
        } else if (property === 'lab-a') {
          lab.a = value;
        } else {
          lab.b = value;
        }
        return Color.fromLab(lab.l, lab.a, lab.b, lab.alpha);
      }
      case 'hue':
      case 'chroma': {
        const lch = color.toLch();
        if (property === 'hue') {
          lch.h = value;
        } else {
          lch.c = value;
        }
        return Color.fromLch(lch.l, lch.c, lch.h, lch.alpha);
      }
      case 'alpha': {
        const hsla = color.toHsla();
        hsla.alpha = value;
        return Color.fromHsla(hsla.h, hsla.s, hsla.l, hsla.alpha);
      }
      default:
        throw new Panic(
          'internal error: entered unreachable code: Unknown property',
          'src/cli/commands/color_commands.rs:200:13',
        );
    }
  }
}
